#ifndef FONT_H
#define FONT_H

#include <stdint.h>

enum font_size {
    FONT_SMALL,
    FONT_MEDIUM,
    FONT_LARGE,
    FONT_TITLE,
};

// Position and size of a glyph relative to the pen on the baseline. Its
// pixels start at offset, 2 bits each, from 0 (empty) to 3 (solid).
struct glyph {
    int8_t x;
    int8_t y;
    uint8_t w;
    uint8_t h;
    uint8_t advance;
    uint16_t offset;
};

struct font {
    int cap_height;
    const struct glyph *glyphs;
    const uint8_t *pixels;
};

// Indexed by font_size, then by Latin-1 character. Generated by tools/font.py.
extern const struct font fonts[];

#endif
